import sys

class Solution:
    def countHighestScoreNodes(self, parents: List[int]) -> int:
        sys.setrecursionlimit(len(parents) + 10)
        n = len(parents)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parents[i]].append(i)
        best = cnt = 0

        def dfs(node):
            nonlocal best, cnt
            size, prod = 1, 1
            for c in children[node]:
                sc = dfs(c)
                size += sc
                prod *= sc
            rest = n - size
            if rest > 0:
                prod *= rest
            if prod > best:
                best, cnt = prod, 1
            elif prod == best:
                cnt += 1
            return size

        dfs(0)
        return cnt

