    int cnt;

    int dfs(int node, vector<vector<int>>& children, int n) {
        long long prod = 1;
        int size = 1;
        for (int c : children[node]) {
            int sc = dfs(c, children, n);
            size += sc;
            prod *= sc;
        }
        long long rest = n - size;
        if (rest > 0) prod *= rest;
        if (prod > best) { best = prod; cnt = 1; }
        else if (prod == best) ++cnt;
        return size;
    }
};

