        for (int i = 1; i < n; i++) children.get(parents[i]).add(i);
        best = 0;
        cnt = 0;
        dfs(0);
        return cnt;
    }

    private int dfs(int node) {
        long prod = 1;
        int size = 1;
        for (int c : children.get(node)) {
            int sc = dfs(c);
            size += sc;
            prod *= sc;
        }
        long rest = n - size;
        if (rest > 0) prod *= rest;
        if (prod > best) { best = prod; cnt = 1; }
        else if (prod == best) cnt++;
        return size;
    }
}

