class Solution {
public:
    int countHighestScoreNodes(vector<int>& parents) {
        int n = parents.size();
        vector<vector<int>> children(n);
        for (int i = 1; i < n; ++i) children[parents[i]].push_back(i);
        vector<int> order;
        order.reserve(n);
        order.push_back(0);
        for (size_t i = 0; i < order.size(); ++i)
            for (int c : children[order[i]]) order.push_back(c);
        vector<int> size(n, 1);
        long long best = 0;
        int cnt = 0;
        for (int j = n - 1; j >= 0; --j) {
            int node = order[j], s = 1;
            long long prod = 1;
            for (int c : children[node]) { s += size[c]; prod *= size[c]; }
            long long rest = n - s;
            if (rest > 0) prod *= rest;
            if (prod > best) { best = prod; cnt = 1; }
            else if (prod == best) ++cnt;
            size[node] = s;
        }
        return cnt;
    }
};

