class Solution {
    public int countHighestScoreNodes(int[] parents) {
        int n = parents.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 1; i < n; i++) children.get(parents[i]).add(i);
        int[] order = new int[n];
        order[0] = 0;
        int head = 0, tail = 1;
        while (head < tail) {
            int node = order[head++];
            for (int c : children.get(node)) order[tail++] = c;
        }
        int[] size = new int[n];
        Arrays.fill(size, 1);
        long best = 0;
        int cnt = 0;
        for (int j = n - 1; j >= 0; j--) {
            int node = order[j], s = 1;
            long prod = 1;
            for (int c : children.get(node)) { s += size[c]; prod *= size[c]; }
            long rest = n - s;
            if (rest > 0) prod *= rest;
            if (prod > best) { best = prod; cnt = 1; }
            else if (prod == best) cnt++;
            size[node] = s;
        }
        return cnt;
    }
};

